            print(json.dumps(result, indent=2))
        if not every or result['complete']:
            break
        page += 1
    if handle:
        handle.close()
        print(json.dumps({'type': first['type'], 'total': first['total'], 'pages': first['pages'], 'written': written, 'file': out}))


